const HERDR_VERSION = "0.9.1";
const recorded = (file: string) => readFileSync(new URL(`./fixtures/${file}`, import.meta.url), "utf8");
const herdrSchema = JSON.parse(recorded(`herdr/${HERDR_VERSION}/schema.json`)).schemas;
