        }); req.on("error", reject); req.end(payload);
      });
      // The watch holds the request; the phone sees the approval until it times out.
      // (An approval answered just before, in another case, can still ride the first frame.)
      await waitFor(() => frames.some(f => f.agentStatus?.pendingApproval?.toolName === "AskUserQuestion"), 3_000);
      expect(frames.find(f => f.agentStatus?.pendingApproval?.toolName === "AskUserQuestion")).toBeDefined();
