      const last = lines.at(-1);
      if (!last) continue;
      const at = Date.parse(last[1]);
      if (at <= latest) continue;
      latest = at;
      current = last[2] === "Registering" && sessionId.safeParse(last[3]).success ? last[3] : undefined;
    } finally { await file.close(); }
  }
