      if (size > 4_096) continue;
      const value = object(JSON.parse((await file.readFile()).toString("utf8")));
      const session = typeof value.session === "string" && /^ses_[0-9A-Za-z]{1,64}$/.test(value.session) ? value.session : undefined;
